music_patch_code="\n# V20.7.16: music links are resource references, never generative prose.\nimport os,re,json,time,base64,hashlib,hmac,threading,urllib.parse\n_MUSIC_LINK_FILE='/memos-data/porfirchik-last-music-links.json'\n_MUSIC_LINK_LOCK=threading.RLock()\n_MUSIC_LINK_REPAIRING=set()\n_MUSIC_LINK_URL_RE=re.compile(r'https?://[A-Za-z0-9.-]+/porfirchik/music/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+')\ndef _music_verified_url(url):\n    try:\n        x=urllib.parse.urlsplit(str(url or ''))\n        base=urllib.parse.urlsplit(os.environ.get('VK_PUBLIC_BASE_URL',''))\n        if x.scheme!='https' or x.hostname!=base.hostname or x.query not in ('','raw=1','download=1'):\n            return None\n        parts=x.path.strip('/').split('/')\n        if len(parts)!=4 or parts[:2]!=['porfirchik','music']:\n            return None\n        sig,encoded=parts[2],parts[3]\n        if not re.fullmatch(r'[a-f0-9]{32}',sig) or not re.fullmatch(r'[A-Za-z0-9_-]{12,512}',encoded):\n            return None\n        secret=os.environ.get('VK_GROUP_TOKEN','').strip()\n        if not secret:\n            return None\n        expected=hashlib.sha256(('music-link:'+secret+':'+encoded).encode('utf-8')).hexdigest()[:32]\n        if not hmac.compare_digest(sig,expected):\n            return None\n        raw=base64.urlsafe_b64decode(encoded+'='*((-len(encoded))%4)).decode('utf-8')\n        if not raw.startswith('disk:/Porfirchik Music/'):\n            return None\n        if not re.fullmatch(r'[A-Za-z0-9_.-]+\\.wav',raw.rsplit('/',1)[-1],re.I):\n            return None\n        return {'path':raw,'url':base.scheme+'://'+base.netloc+x.path}\n    except (ValueError,UnicodeError,TypeError):\n        return None\n\ndef _music_valid_urls(message):\n    return [x for x in\n            (_music_verified_url(m.group(0)) for m in _MUSIC_LINK_URL_RE.finditer(str(message or '')))\n            if x]\n\ndef _music_links_read():\n    try:\n        with _MUSIC_LINK_LOCK:\n            with open(_MUSIC_LINK_FILE,'r',encoding='utf-8') as f:\n                data=json.load(f)\n        return data if isinstance(data,dict) else {}\n    except (OSError,ValueError,TypeError):\n        return {}\n\ndef _music_links_save(uid,record):\n    if not record or not _music_verified_url(record.get('url','')):\n        return\n    try:\n        with _MUSIC_LINK_LOCK:\n            data=_music_links_read()\n            data[str(uid)]={'path':record['path'],'url':record['url'],'at':int(time.time())}\n            # A bounded per-user index, not an unbounded audio-data cache.\n            if len(data)>40:\n                data=dict(sorted(data.items(),key=lambda p:p[1].get('at',0),reverse=True)[:40])\n            os.makedirs('/memos-data',exist_ok=True)\n            tmp=_MUSIC_LINK_FILE+'.tmp'\n            with open(tmp,'w',encoding='utf-8') as f:\n                json.dump(data,f,ensure_ascii=False)\n            os.replace(tmp,_MUSIC_LINK_FILE)\n    except (OSError,ValueError,TypeError) as err:\n        print('MUSIC_LINK_INDEX_WRITE_ERROR',type(err).__name__,flush=True)\n\n_base_music_send=send\ndef send(peer,text):\n    msg=str(text or '')\n    has_music_url='/porfirchik/music/' in msg or 'yadi.sk/' in msg or 'disk.yandex.ru/d/' in msg\n    verified=_music_valid_urls(msg)\n    if has_music_url and not verified:\n        state['music_fake_link_blocked']=int(state.get('music_fake_link_blocked') or 0)+1\n        recent=_music_links_read().get(str(peer),{})\n        cached=_music_verified_url(recent.get('url',''))\n        msg=('Не могу подтвердить ссылку на музыкальный файл. '\n             'Нельзя придумывать адрес скачивания.')\n        if cached:\n            msg+=' Последняя сохранённая ссылка: '+cached['url']\n        else:\n            msg+=' Напиши «повтори ссылку на музыку», и я проверю сохранённый файл.'\n        print('MUSIC_UNVERIFIED_LINK_BLOCKED',flush=True)\n    result=_base_music_send(peer,msg)\n    if verified and 'Музыка готова. Сохранил WAV' in msg:\n        _music_links_save(peer,verified[0])\n    return result\n\ndef _music_link_request(text):\n    t=str(text or '').lower().strip()\n    if t.startswith('/musiclink') or t.startswith('/музыка-ссылка'):\n        return True\n    if 'ссылк' not in t and 'скач' not in t and 'не открыва' not in t:\n        return False\n    # Explicit new-generation commands must remain music-generation requests.\n    new_track=('сгенерируй','сочини','запиши','новый трек','новую песню',\n               'создай трек','создай музыку','сделай музыку')\n    if any(k in t for k in new_track):\n        return False\n    if any(k in t for k in ('музык','трек','песн','wav','аудио','файл')):\n        return True\n    return any(k in t for k in ('не открывается','не открывает','не работает',\n             'не скачивается','эту ссылку','новую ссылку','повтори ссылку',\n             'пришли ссылку','дай ссылку'))\n\ndef _music_link_repair_worker(uid,request_text):\n    try:\n        candidates=_music_valid_urls(request_text)\n        saved=_music_links_read().get(str(uid),{})\n        cached=_music_verified_url(saved.get('url',''))\n        if cached:\n            candidates.append(cached)\n        if not candidates:\n            try:\n                history=_music_vk_api('messages.getHistory',{'peer_id':int(uid),'count':90}) or {}\n                for item in history.get('items') or []:\n                    if item.get('out'):\n                        candidates.extend(_music_valid_urls(item.get('text','')))\n            except Exception as err:\n                print('MUSIC_LINK_HISTORY_ERROR',type(err).__name__,flush=True)\n        seen=set()\n        for record in candidates:\n            path=record['path']\n            if path in seen:\n                continue\n            seen.add(path)\n            try:\n                meta=_music_yandex_api('/resources',{'path':path})\n                size=int(meta.get('size') or 0)\n                if size<44 or size>35000000:\n                    continue\n                _music_links_save(uid,record)\n                send(uid,'Проверенная ссылка на уже сохранённый WAV, без новой генерации: '+record['url'])\n                state['music_link_repair_last_ok']=True\n                print('MUSIC_LINK_REISSUE_OK',json.dumps({'bytes':size}),flush=True)\n                return\n            except Exception as err:\n                print('MUSIC_LINK_RESOURCE_UNAVAILABLE',type(err).__name__,flush=True)\n                if len(seen)>=5:\n                    break\n        state['music_link_repair_last_ok']=False\n        send(uid,'Не нашёл подтверждённого сохранённого WAV. '\n             'Непроверенную ссылку присылать не буду. '\n             'Если у тебя есть старая ссылка, пришли её целиком для проверки.')\n    finally:\n        with _MUSIC_LINK_LOCK:\n            _MUSIC_LINK_REPAIRING.discard(str(uid))\n\n_old_music_routed_response=routed_response\ndef routed_response(uid,text):\n    if not _music_link_request(text):\n        return _old_music_routed_response(uid,text)\n    with _MUSIC_LINK_LOCK:\n        if str(uid) in _MUSIC_LINK_REPAIRING:\n            return 'Уже проверяю сохранённый файл; повторно создавать музыку не нужно.'\n        _MUSIC_LINK_REPAIRING.add(str(uid))\n    threading.Thread(target=_music_link_repair_worker,args=(uid,text),daemon=True).start()\n    return 'Проверяю WAV на Яндекс.Диске и пришлю подтверждённую ссылку отдельным сообщением.'\n\nstate['music_links_policy']='verified-only+persisted-last-by-peer+no-regenerate-for-reissue'\nprint('ND_V20_7_16_MUSIC_LINK_GUARD_READY',flush=True)\n"
